insert into assessments (slug, title, short_description, long_description, icon, category_id, engine_type, difficulty, estimated_duration_minutes, question_count, featured, access, status) values ('creative-divergent-thinking', 'Creative Divergent Thinking', 'Alternative-uses and idea-fluency tasks that measure how many genuinely different directions you can generate.', 'Creative Divergent Thinking combines two classic, complementary creativity paradigms. The Alternative Uses Task (Guilford, 1967) asks you to generate as many different uses as you can for an everyday object — the foundational measure of idea fluency and divergent thinking, scored here by AI interpretation rather than a right/wrong answer, since the point is open-ended generation. The Remote Associates Test (Mednick, 1962) asks you to find the single word that connects three seemingly unrelated words — a convergent-creativity measure with objectively correct answers, scored deterministically.', 'shuffle', (select id from assessment_categories where key = 'creative'), ('hybrid')::assessment_engine_type, ('medium')::assessment_difficulty, 15, 10, false, ('premium')::assessment_access, ('published')::assessment_status)
insert into scoring_dimensions (assessment_id, key, label, description, contributes_to_brain_profile, brain_profile_dimension_key, "order") values ((select id from assessments where slug = 'creative-divergent-thinking'), 'convergent-creativity', 'Remote Associates (Convergent Creativity)', 'Finding the single connecting concept across three unrelated words.', true, 'creative', 1)
insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values ((select id from assessments where slug = 'creative-divergent-thinking'), 'overall', 0, 30, 'Developing', 'Spotting the connecting concept across unrelated words is difficult right now — your idea-generation on the alternative-uses prompts is interpreted separately below.', ARRAY['Practice free-associating around each given word before looking for overlap with the others', convert_from(decode('Rm9yIGFsdGVybmF0aXZlIHVzZXMsIHB1c2ggcGFzdCB0aGUgZmlyc3QgMi0zIG9idmlvdXMgYW5zd2VycyDigJQgZ2VudWluZWx5IGRpZmZlcmVudCBjYXRlZ29yaWVzIG9mIHVzZSBhcmUgd2hhdCdzIGJlaW5nIG1lYXN1cmVk', 'base64'), 'UTF8'), 'Read your AI interpretation below for feedback on the open-ended prompts specifically']::text[], NULL, 1);
insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values ((select id from assessments where slug = 'creative-divergent-thinking'), 'overall', 31, 50, 'Average', 'Some remote-associate connections found, others elusive — a normal split on a genuinely difficult task type.', ARRAY['Try approaching each word from multiple senses (literal, compound, homophone) before moving on', 'On alternative uses, deliberately shift categories (not just size/shape variations of the same idea)']::text[], NULL, 2);
insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values ((select id from assessments where slug = 'creative-divergent-thinking'), 'overall', 51, 70, 'Strong', 'Reliable at finding the connecting concept across most word triads.', ARRAY['Push into remote associates with less obvious connecting words to sharpen this further', 'Notice which alternative-uses categories you gravitate toward, and deliberately branch into unfamiliar ones']::text[], NULL, 3);
insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values ((select id from assessments where slug = 'creative-divergent-thinking'), 'overall', 71, 85, 'Very Strong', 'Consistently finds the connecting concept, including on the less obvious triads.', ARRAY['This convergent-creativity skill pairs well with strong divergent output — check your AI interpretation for how they compare', 'Try timed remote-associates practice to push speed alongside accuracy']::text[], NULL, 4);
insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values ((select id from assessments where slug = 'creative-divergent-thinking'), 'overall', 86, 100, 'Exceptional', 'Near-perfect at finding the connecting concept across every word triad.', ARRAY['This level of associative fluency is a genuine asset in ideation-heavy or naming-heavy work', 'Consider how it pairs with your divergent-thinking results from the alternative-uses prompts']::text[], NULL, 5);
