insert into assessment_sections (assessment_version_id, name, description, instructions, time_limit_seconds, randomize_questions, weight, "order") values ((select current_version_id from assessments where slug = 'creative-divergent-thinking'), 'Alternative Uses', 'Generate as many different uses as you can for an everyday object.', convert_from(decode('TGlzdCBhcyBtYW55IGRpZmZlcmVudCwgZ2VudWluZWx5IGRpc3RpbmN0IHVzZXMgYXMgeW91IGNhbiB0aGluayBvZi4gUXVhbnRpdHkgYW5kIHZhcmlldHkgYm90aCBtYXR0ZXIgbW9yZSB0aGFuIGFueSBzaW5nbGUgImJlc3QiIGFuc3dlci4=', 'base64'), 'UTF8'), NULL, false, 0.5, 2);
